// SPDX-License-Identifier: UNLICENSED
// Copyright (c) 2025 Aave Labs
pragma solidity ^0.8.0;

import 'tests/unit/Hub/HubBase.t.sol';

contract HubMintFeeSharesTest is HubBase {
  function test_mintFeeShares_revertsWith_AccessManagedUnauthorized() public {
    vm.expectRevert(
      abi.encodeWithSelector(IAccessManaged.AccessManagedUnauthorized.selector, address(this))
    );
    Utils.mintFeeShares(hub1, daiAssetId, address(this));
  }

  function test_mintFeeShares_revertsWith_SpokeNotActive() public {
    // Create debt to build up fees on the existing treasury spoke
    _addAndDrawLiquidity({
      hub: hub1,
      assetId: daiAssetId,
      addUser: bob,
      addSpoke: address(spoke1),
      addAmount: 100e18,
      drawUser: bob,
      drawSpoke: address(spoke1),
      drawAmount: 10e18,
      skipTime: 365 days
    });

    _updateSpokeActive(hub1, daiAssetId, _getFeeReceiver(hub1, daiAssetId), false);
    vm.expectRevert(IHub.SpokeNotActive.selector, address(hub1));
    Utils.mintFeeShares(hub1, daiAssetId, ADMIN);
  }

  function test_mintFeeShares_revertsWith_AssetNotListed() public {
    uint256 invalidAssetId = hub1.getAssetCount();
    vm.expectRevert(IHub.AssetNotListed.selector);
    Utils.mintFeeShares(hub1, invalidAssetId, ADMIN);
  }

  function test_mintFeeShares() public {
    // Create debt to build up fees on the existing treasury spoke
    _addAndDrawLiquidity({
      hub: hub1,
      assetId: daiAssetId,
      addUser: bob,
      addSpoke: address(spoke1),
      addAmount: 1000e18,
      drawUser: bob,
      drawSpoke: address(spoke1),
      drawAmount: 100e18,
      skipTime: 365 days
    });

    address feeReceiver = _getFeeReceiver(hub1, daiAssetId);

    // before mintFeeShares, the fee shares should be 0
    uint256 realizedFees = hub1.getAsset(daiAssetId).realizedFees;
    assertEq(realizedFees, 0);
    uint256 feeShares = hub1.getSpokeAddedShares(daiAssetId, feeReceiver);
    assertEq(feeShares, 0);

    uint256 expectedMintedAssets = _getExpectedFeeReceiverAddedAssets(hub1, daiAssetId);
    uint256 expectedMintedShares = hub1.previewAddByAssets(daiAssetId, expectedMintedAssets);

    IHub.Asset memory asset = hub1.getAsset(daiAssetId);
    bytes memory irCalldata = abi.encodeCall(
      IBasicInterestRateStrategy.calculateInterestRate,
      (
        daiAssetId,
        asset.liquidity,
        hub1.previewRestoreByShares(daiAssetId, hub1.getAssetDrawnShares(daiAssetId)),
        asset.deficitRay,
        asset.swept
      )
    );
    uint256 mockRate = 0.3e27;
    vm.mockCall(address(irStrategy), irCalldata, abi.encode(mockRate));

    // after mintFeeShares, the fee shares should be the amount of the fees
    vm.expectEmit(address(hub1));
    emit IHub.MintFeeShares(daiAssetId, feeReceiver, expectedMintedShares, expectedMintedAssets);
    vm.expectEmit(address(hub1));
    emit IHub.UpdateAsset(daiAssetId, hub1.getAssetDrawnIndex(daiAssetId), mockRate, 0);

    uint256 addedSharesBefore = hub1.getAddedShares(daiAssetId);
    uint256 sharePriceBefore = hub1.previewAddByShares(daiAssetId, 1e18);

    vm.expectCall(address(irStrategy), irCalldata);
    uint256 mintedShares = Utils.mintFeeShares(hub1, daiAssetId, ADMIN);

    assertEq(mintedShares, expectedMintedShares, 'minted shares');
    assertEq(hub1.getAsset(daiAssetId).realizedFees, 0, 'realized fees after');
    assertEq(
      hub1.getSpokeAddedShares(daiAssetId, feeReceiver),
      expectedMintedShares,
      'added shares'
    );
    assertEq(mintedShares, hub1.getAddedShares(daiAssetId) - addedSharesBefore, 'minted shares');
    assertGe(hub1.previewAddByShares(daiAssetId, 1e18), sharePriceBefore, 'share price');
  }

  function test_mintFeeShares_noFees() public {
    test_mintFeeShares();

    IHub.Asset memory asset = hub1.getAsset(daiAssetId);

    // pausing the fee receiver does not revert the action since no shares are minted
    _updateSpokeActive(hub1, daiAssetId, _getFeeReceiver(hub1, daiAssetId), false);

    vm.expectEmit(address(hub1));
    emit IHub.UpdateAsset(daiAssetId, asset.drawnIndex, asset.drawnRate, 0);

    vm.recordLogs();
    Utils.mintFeeShares(hub1, daiAssetId, ADMIN);
    vm.getRecordedLogs();
    _assertEventNotEmitted(IHub.MintFeeShares.selector);
  }

  function test_mintFeeShares_noShares() public {
    updateLiquidityFee(hub1, daiAssetId, 0);
    _mockInterestRateRay(2);

    // Create debt to build up fees on the existing treasury spoke
    _addAndDrawLiquidity({
      hub: hub1,
      assetId: daiAssetId,
      addUser: bob,
      addSpoke: address(spoke1),
      addAmount: 3,
      drawUser: bob,
      drawSpoke: address(spoke1),
      drawAmount: 1,
      skipTime: 365 days
    });

    // drawn index is 1.0000...002
    assertEq(hub1.getAssetDrawnIndex(daiAssetId), 1e27 + 2);

    _mockInterestRateRay(1e27 - 3);
    updateLiquidityFee(hub1, daiAssetId, PercentageMath.PERCENTAGE_FACTOR);

    // mint fee shares just to accrue (liquidity fee is 0, so no fees are minted)
    Utils.mintFeeShares(hub1, daiAssetId, ADMIN);
    skip(365 days);

    // drawn index is 2.000...001
    assertEq(hub1.getAssetDrawnIndex(daiAssetId), 2e27 + 1);

    vm.recordLogs();
    Utils.mintFeeShares(hub1, daiAssetId, ADMIN);
    vm.getRecordedLogs();
    _assertEventNotEmitted(IHub.MintFeeShares.selector);

    assertEq(hub1.getAsset(daiAssetId).realizedFees, 1, 'realized fees after');
  }
}

project/tests/unit/Hub/Hub.PayFee.t.sol.content:
// SPDX-License-Identifier: UNLICENSED
// Copyright (c) 2025 Aave Labs
pragma solidity ^0.8.0;

import 'tests/unit/Hub/HubBase.t.sol';

contract HubPayFeeTest is HubBase {
  function test_payFee_revertsWith_InvalidShares() public {
    vm.expectRevert(IHub.InvalidShares.selector, address(hub1));
    vm.prank(address(spoke1));
    hub1.payFeeShares(daiAssetId, 0);
  }

  function test_payFee_revertsWith_SpokeNotActive() public {
    _updateSpokeActive(hub1, daiAssetId, address(spoke1), false);
    vm.expectRevert(IHub.SpokeNotActive.selector, address(hub1));
    vm.prank(address(spoke1));
    hub1.payFeeShares(daiAssetId, 1);
  }

  function test_payFee_revertsWith_underflow_added_shares_exceeded() public {
    uint256 addAmount = 100e18;
    Utils.add({
      hub: hub1,
      assetId: daiAssetId,
      caller: address(spoke1),
      amount: addAmount,
      user: alice
    });

    uint256 feeShares = hub1.getSpokeAddedShares(daiAssetId, address(spoke1));

    vm.expectRevert(stdError.arithmeticError);
    vm.prank(address(spoke1));
    hub1.payFeeShares(daiAssetId, feeShares + 1);
  }

  function test_payFee_revertsWith_underflow_added_shares_exceeded_with_interest() public {
    uint256 addAmount = 100e18;
    Utils.add({
      hub: hub1,
      assetId: daiAssetId,
      caller: address(spoke1),
      amount: addAmount,
      user: alice
    });

    _addLiquidity(daiAssetId, addAmount);
    _drawLiquidity(daiAssetId, addAmount, true);

    uint256 feeShares = hub1.getSpokeAddedShares(daiAssetId, address(spoke1));
    uint256 feeAmount = hub1.getSpokeAddedAssets(daiAssetId, address(spoke1));

    // supply ex rate increases due to interest
    assertGt(feeAmount, feeShares);

    vm.expectRevert(stdError.arithmeticError);
    vm.prank(address(spoke1));
    hub1.payFeeShares(daiAssetId, feeShares + 1);
  }

  function test_payFee_fuzz(uint256 addAmount, uint256 feeShares) public {
    test_payFee_fuzz_with_interest(addAmount, feeShares, 0);
  }

  function test_payFee_fuzz_with_interest(
    uint256 addAmount,
    uint256 feeShares,
    uint256 skipTime
  ) public {
    addAmount = bound(addAmount, 1, MAX_SUPPLY_AMOUNT);
    skipTime = bound(skipTime, 0, MAX_SKIP_TIME);

    Utils.add({
      hub: hub1,
      assetId: daiAssetId,
      caller: address(spoke1),
      amount: addAmount,
      user: alice
    });

    _addLiquidity(daiAssetId, 100e18);
    _drawLiquidity(daiAssetId, 100e18, true);

    uint256 spokeSharesBefore = hub1.getSpokeAddedShares(daiAssetId, address(spoke1));

    // supply ex rate increases due to interest
    assertGe(hub1.previewRemoveByShares(daiAssetId, WadRayMath.RAY), WadRayMath.RAY);

    feeShares = bound(feeShares, 1, spokeSharesBefore);

    uint256 feeReceiverSharesBefore = hub1.getSpokeAddedShares(
      daiAssetId,
      _getFeeReceiver(hub1, daiAssetId)
    );

    vm.expectEmit(address(hub1));
    emit IHubBase.TransferShares(
      daiAssetId,
      address(spoke1),
      _getFeeReceiver(hub1, daiAssetId),
      feeShares
    );

    vm.prank(address(spoke1));
    hub1.payFeeShares(daiAssetId, feeShares);

    _assertBorrowRateSynced(hub1, daiAssetId, 'payFee');
    _assertHubLiquidity(hub1, daiAssetId, 'payFee');
    uint256 spokeSharesAfter = hub1.getSpokeAddedShares(daiAssetId, address(spoke1));
    uint256 feeReceiverSharesAfter = hub1.getSpokeAddedShares(
      daiAssetId,
      _getFeeReceiver(hub1, daiAssetId)
    );

    assertEq(spokeSharesAfter, spokeSharesBefore - feeShares, 'spoke supplied shares after');
    assertEq(
      feeReceiverSharesAfter,
      feeReceiverSharesBefore + feeShares,
      'fee receiver supplied shares after'
    );
  }
}

