  }

  function test_approveWithdrawWithSig_revertsWith_SpokeNotRegistered() public {
    ITakerPositionManager.WithdrawPermit memory p = _withdrawPermitData(
      bob,
      alice,
      _warpBeforeRandomDeadline()
    );
