    _withdrawLiquidityFees(hub1, assetId, UINT256_MAX);

    // Time passes
    skip(skipTime);

    // Alice supplies 1 share to trigger interest accrual
    Utils.supply(spoke1, reserveId, alice, minimumAssetsPerAddedShare(hub1, assetId), alice);

    // treasury
