    );

    _assertUserPositionAndDebt({
      spoke: spoke1,
      reserveId: state.daiReserveId,
      user: bob,
      debtAmount: state.daiBob.borrowAmount,
      suppliedAmount: 0,
      expectedPremiumDebtRay: state.daiBob.premiumDebtRayBefore,
      label: 'bob dai data after'
    });
    _assertUserPositionAndDebt({
      spoke: spoke1,
      reserveId: state.wethReserveId,
      user: bob,
      debtAmount: 0,
