      expectedPremiumDebtRay: state.wethBob.premiumDebtRayBefore,
      label: 'bob weth data after'
    });
    _assertUserPositionAndDebt({
      spoke: spoke1,
      reserveId: state.daiReserveId,
      user: alice,
      debtAmount: 0,
