        deal(address(tokenList.dai), user, usersInfo[i].daiInfo.repayAmount);
        Utils.repay(spoke1, _daiReserveId(spoke1), user, usersInfo[i].daiInfo.repayAmount, user);
      }

      // Check Dai Repayment
