    // cannot withdraw any amount of dai (HF already < threshold)
    vm.prank(bob);
    vm.expectRevert(ISpoke.HealthFactorBelowThreshold.selector);
    spoke1.withdraw({reserveId: daiReserveId, amount: 1, onBehalfOf: bob});
  }

